import {useState} from 'react';import {createRoot} from 'react-dom/client';import {MemoryRouter} from 'react-router-dom';import {HelmetProvider} from 'react-helmet-async';import {QueryClientProvider} from '@tanstack/react-query';import {createJSONStorage} from 'zustand/middleware';
import axiosClient from '../../src/api/axiosClient';import {queryClient} from '../../src/api/queryClient';import {useAuthStore} from '../../src/stores/useAuthStore';import ProductManagementPage from '../../src/pages/ProductManagementPage';import type {ProductItem} from '../../src/types/catalog';import '../../src/index.css';
const params=new URLSearchParams(location.search),scenario=params.get('case')??'normal',memory=new Map<string,string>(),storage={getItem:(key:string)=>memory.get(key)??null,setItem:(key:string,value:string)=>{memory.set(key,value);},removeItem:(key:string)=>{memory.delete(key);}};
Object.defineProperty(window,'localStorage',{value:storage,configurable:true});useAuthStore.persist.setOptions({storage:createJSONStorage(()=>storage)});useAuthStore.setState({token:'products-fixture-a',user:{id:999994,email:'admin@example.invalid',role:'Admin',fullName:'Quản trị viên kiểm thử'}});
let rows:ProductItem[]=[{id:41,categoryId:3,categoryName:'Rau củ',name:scenario==='long'?'Giỏ rau tổng hợp kiểm thử với tên sản phẩm dài '.repeat(5):'Giỏ rau tổng hợp',price:185000,stockQuantity:24,isHot:true,isAvailable:true,imageUrl:'/src/assets/home-groceries.jpg',imagePublicId:'fixture/original',origin:'Việt Nam',description:'Dữ liệu kiểm thử, không phải sản phẩm đang bán.'},{id:42,categoryId:3,categoryName:'Rau củ',name:'Cà chua',price:45000,stockQuantity:0,isHot:false,isAvailable:false},{id:43,categoryId:4,categoryName:'Thực phẩm khác',name:'Nấm tươi',price:65000,stockQuantity:8,isHot:false,isAvailable:false,imageUrl:'/fixture-image-missing.jpg'},{id:44,categoryId:4,categoryName:'Thực phẩm khác',name:'Gạo trắng',price:32000,stockQuantity:65,isHot:false,isAvailable:true}];
let productReads=0,categoryReads=0,writes=0,uploads=0,lastBody='',lastUrl='',failNext=false,pending:(()=>void)[]=[];
axiosClient.defaults.adapter=async config=>{const path=new URL(config.url!,'http://fixture.invalid').pathname;let data:unknown;
 if(config.method==='get'){const isCategories=path==='/api/categories';if(isCategories)categoryReads++;else productReads++;const snapshot=rows;if(scenario==='slow')await new Promise<void>(resolve=>pending.push(resolve));if((isCategories&&scenario==='category-error')||(!isCategories&&((scenario==='error'&&productReads===1)||failNext))){failNext=false;throw Error('Isolated failure');}data=isCategories?(scenario==='no-categories'?[]:[{id:3,name:'Rau củ'},{id:4,name:'Thực phẩm khác'}]):scenario==='malformed'?[{id:1,price:null}]:scenario==='empty'?[]:snapshot;}
 else if(path==='/api/upload/image'){uploads++;if(scenario==='upload-error'&&uploads===1)throw Error('Upload fixture failed');data={url:'http://localhost:5173/src/assets/home-groceries.jpg',publicId:'fixture/new-image'};}
 else if(['post','put','patch'].includes(config.method??'')){writes++;lastBody=String(config.data);lastUrl=path;if(scenario==='write-slow')await new Promise<void>(resolve=>pending.push(resolve));if(scenario==='save-error'&&writes===1)throw Error('Save fixture failed');const body=JSON.parse(String(config.data));if(config.method==='post'){const categoryName=body.categoryId===3?'Rau củ':'Thực phẩm khác';data={...body,id:45,categoryName,isAvailable:body.stockQuantity>0};rows=[data as ProductItem,...rows];}else{const id=Number(path.split('/')[3]);rows=rows.map(row=>row.id!==id?row:config.method==='patch'?{...row,stockQuantity:row.stockQuantity+body.quantity,isAvailable:true}:{...row,...body});data=rows.find(row=>row.id===id);}}
 else throw Error('Unexpected operation blocked');return {data,status:200,statusText:'OK',headers:{},config};};queryClient.setDefaultOptions({queries:{retry:false}});
export function Fixture(){const[version,refresh]=useState(0);return <><aside style={{display:params.has('compact')?'none':undefined,padding:10,fontSize:12,background:'#fffbeb',color:'#78350f',overflowWrap:'anywhere'}}><p>KIỂM THỬ CÁCH LY — dữ liệu và thao tác minh họa, không gửi API thật.</p><button onClick={()=>{pending.splice(0).forEach(resolve=>resolve());refresh(version+1);}}>Cho phép phản hồi</button>{' · '}<button onClick={()=>{failNext=true;refresh(version+1);}}>Lỗi lần tải tiếp</button>{' · '}<button onClick={()=>{rows=[];useAuthStore.getState().login('products-fixture-b',{id:999993,role:'Admin',fullName:'Quản trị B',email:'b@example.invalid'});refresh(version+1);}}>Đổi tài khoản</button>{' · '}<button onClick={()=>refresh(version+1)}>Đọc bộ đếm</button><output style={{display:'block',wordBreak:'break-all'}} data-testid="fixture-state">{JSON.stringify({productReads,categoryReads,writes,uploads,lastUrl,lastBody,pending:pending.length,version})}</output></aside><ProductManagementPage/></>}
createRoot(document.getElementById('root')!).render(<HelmetProvider><QueryClientProvider client={queryClient}><MemoryRouter initialEntries={['/admin/products']}><Fixture/></MemoryRouter></QueryClientProvider></HelmetProvider>);
